import { readFile, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const packageRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const packageJsonPath = join(packageRoot, 'package.json');
const outputPath = join(packageRoot, 'src/core/sdk-info.ts');

const packageInfo = JSON.parse(await readFile(packageJsonPath, 'utf8'));

const content = `// This file is generated by scripts/generate-sdk-info.mjs.
// Do not edit it by hand.
export const appObservatorySdkInfo = {
  name: ${JSON.stringify(packageInfo.name)},
  version: ${JSON.stringify(packageInfo.version)},
} as const;
`;

await writeFile(outputPath, content);
